# פרק 8 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=8
TITLE='תקיפה וכליאת שווא'
SUM=[' <p>שתי עוולות פרטיקולריות המגִנות על שלמות הגוף ועל חירות התנועה.</p> <h3>8.1 תקיפה — סעיף 23</h3> <p>"שימוש בכוח מכל סוג שהוא, ובמתכוון, נגד גופו של אדם... שלא בהסכמתו או בהסכמה שהושגה בתרמית". כולל גם <strong>ניסיון או איום</strong> להשתמש בכוח כשהמאוים מניח מטעמים סבירים שיש כוונה ויכולת לבצעו. "כוח" כולל חום, אור, חשמל, גז וריח. נדרשת <strong>כוונה לעצם המגע</strong> (לא בהכרח לנזק).</p> <h3>8.2 כליאת שווא — סעיף 26</h3> <p>שלילת חירותו של אדם, <strong>שלא כדין</strong>, באופן מוחלט ולפרק זמן כלשהו — בכוח או באיום. די בכליאה קצרה, ואין צורך בנזק ממשי או במחיצות פיזיות (די במניעת יציאה).</p> <h3>8.3 עוולות פרטיקולריות מול רשלנות</h3> <p>בשונה מהרשלנות (עוולת מסגרת), אלה עוולות עם <strong>יסודות מוגדרים</strong>. עצם הפגיעה בזכות מקימה עילה (אם כי שיעור הפיצוי תלוי בנזק).</p> <h3>8.4 נקודות מפתח למבחן</h3> <ul><li>תקיפה (ס׳ 23) — כוונה למגע, כולל איום; "כוח" במובן רחב.</li><li>כליאת שווא (ס׳ 26) — שלילת חירות מוחלטת ושלא כדין.</li><li>עוולות עם יסודות מוגדרים מול עוולת מסגרת.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[("ס' 23 לפקודת הנזיקין — תקיפה", '', 'שימוש מכוון בכוח נגד גופו של אדם ללא הסכמה, לרבות ניסיון או איום אמין; "כוח" כולל חום, אור, חשמל וריח מזיקים.'), ("ס' 26 לפקודת הנזיקין — כליאת שווא", '', 'שלילת חירות התנועה של אדם, שלא כדין, באופן מוחלט ולו לזמן קצר — ללא צורך במחיצות פיזיות או בנזק.'), ('עוולות פרטיקולריות', '', 'עוולות בעלות יסודות מוגדרים (בשונה מעוולות המסגרת) המגִנות על שלמות הגוף וחירות התנועה.'), ('ע״א 358/63 מדינת ישראל נ׳ שוורץ', 'אדם תבע את המדינה, את מנהל בית הסוהר ואת הסוהרים על חבלות שנגרמו לו ממכות של שוטרים בעת מעצרו ושל סוהרים בזמן כליאתו.', 'המדינה, כמו כל תאגיד, אחראית שילוחית לעוולות שעובדיה עושים במהלך תפקידם, ויכולה לשאת באחריות גם כשהרשתה או אישררה מעשים שאינם בגדר התפקיד. פסק הדין הוא בסיס לתביעות נגד המדינה על אלימות שוטרים וסוהרים.'), ('רע״א 1272/05 כרמי נ׳ סבג', 'אדם שסבל ממחלת נפש תקף ופצע קשה ילד בן שמונה. בהליך הפלילי נמצא שאינו אחראי למעשיו, והילד תבע אותו בנזיקין.', 'בנזיקין אין הגנת אי־שפיות במובן הפלילי (אי־הבנה של המעשה או של פסלותו, או חוסר יכולת להימנע ממנו). ההגנה היחידה היא חוסר שליטה ממש במעשה, כמו אוטומטיזם. התוקף חויב.'), ('ע״א 2781/93 דעקה נ׳ בית החולים ״כרמל״, חיפה', 'מטופלת שאושפזה לניתוח ברגל התבקשה, כשכבר הייתה על שולחן הניתוחים ותחת תרופות הרגעה, לחתום על הסכמה לביופסיה בכתף. הכתף נותרה נוקשה.', 'בית החולים התרשל כשלא קיבל ממנה הסכמה מדעת. מכיוון שנמצא שהייתה מסכימה גם אילו קיבלה הסבר, לא הוכח קשר סיבתי לנזק הגוף, אבל הוכר ראש נזק נפרד של פגיעה באוטונומיה. הפרשה מראה שהעדר מידע על טיפול שהוסכם נבחן במסגרת הרשלנות ולא כתקיפה.'), ('ע״א 558/84 כרמלי נ׳ מדינת ישראל', 'אישה אושפזה בכפייה, והבדיקה הפסיכיאטרית שהחוק חייב בתוך מספר ימים לא נעשתה במועד. היא תבעה על כליאת שווא ועל הפרת חובה חקוקה.', 'הפרשה ממחישה את מה שמכונה בספרות גישת ״הרשתות״ — אפשר לטעון כמה עוולות על אותן עובדות (כאן: כליאת שווא, שלגביה נטענה הגנת ס׳ 27(3), והפרת חובה חקוקה), והפיצוי הוא פונקציה של הנזק. התביעה נדחתה, משום שגם אילו נבדקה במועד הייתה נשארת מאושפזת, ולכן הפגם לא גרם לה נזק בר־פיצוי.'), ('ע״א 3510/99 וולאס נ׳ אגד', 'נוסע שחיכה לאוטובוס בתחנה המרכזית הוכה קשות בידי צעיר וחבריו. הוא תבע את התוקף ואת אגד, בטענה לרשלנות ולהפרת חובה חקוקה בכך שלא הוצב מאבטח.', 'לא היה מקום לדחות את התביעה נגד אגד על הסף. העובדה שהתקיפה הייתה ספונטנית ובלי התגרות אינה מוציאה אותה מתחום האחריות הנזיקית. שאלת החובה לנקוט אמצעים למניעת מעשה פלילי של צד שלישי והקשר הסיבתי טעונות בירור עובדתי.')]
QS=[{'q': 'מה מהבאים הוא יסוד בעוולת התקיפה לפי ס׳ 23?', 'o': ['כוונה לגרום נזק גופני', 'שימוש בכוח במתכוון נגד גופו של אדם, שלא בהסכמתו', 'חבלה של ממש', 'מגע ישיר בין גוף התוקף לגוף הנתקף'], 'c': 1, 'e': 'נכון. אלה רכיבי הליבה של ס׳ 23(א): כוח מכל סוג, במתכוון, נגד הגוף, ובלי הסכמה.'}, {'q': 'אדם משך את הכיסא מתחת לחברו כשזה התיישב, והחבר נפל. האם זו תקיפה?', 'o': ['רק אם נגרמה חבלה של ממש', 'לא, כי לא הייתה כוונה לפגוע', 'לא, כי לא היה מגע בין השניים', 'כן — שימוש מכוון בכוח בעקיפין נגד הגוף, בלי הסכמה'], 'c': 3, 'e': 'נכון. זו דוגמה קלאסית לתקיפה עקיפה ומכוונת.'}, {'q': 'נהג רכב פגע בטעות בהולך רגל משום שהביט בטלפון. מה העוולה המתאימה?', 'o': ['אין עוולה כלל', 'כליאת שווא', 'תקיפה, כי היה מגע בכוח', 'רשלנות, כי לא הייתה כוונה למגע'], 'c': 3, 'e': 'נכון. כשהמגע אינו מכוון, המסלול הוא עוולת הרשלנות (ובתאונות דרכים — החוק המיוחד לפיצוי נפגעים, הנלמד בשיעור 15).'}, {'q': 'איזה מהמצבים הבאים מקיים ״תקיפה בדרך של איום״ לפי ס׳ 23?', 'o': ['שליחת הודעה: ״בשבוע הבא אשבור לך את הרגליים״', 'אדם מניף אגרוף מול פני חברו במרחק צעד ממנו, והחבר נרתע', 'צעקה מהקומה העשירית על אדם שעומד ברחוב, בלי שום דרך להגיע אליו', 'כתיבת פוסט פוגעני ברשת'], 'c': 1, 'e': 'נכון. יש תנועה, והנחה סבירה לכוונה וליכולת מיידיות.'}, {'q': 'מה קובע ס׳ 23(ב) לפקודה?', 'o': ['שתקיפה מחייבת פיצוי עונשי', 'שתקיפה של קטין מתחת לגיל 12 אינה עוולה', 'ששימוש בחום, אור, חשמל, גז, ריח או חומר אחר נחשב שימוש בכוח, אם נעשה במידה שיש בה להזיק', 'שאיום במילים בלבד הוא תקיפה'], 'c': 2, 'e': 'נכון. זו לשון הסעיף, כולל הסייג ״במידה שיש בה להזיק״.'}, {'q': 'מטופלת הסכימה לניתוח ברגל, והמנתח החליט לבצע באותו ניתוח גם הליך בכתף, בלי לשאול אותה. כיצד יש לסווג זאת?', 'o': ['זו ככל הנראה תקיפה — פעולה שונה מהותית ממה שהוסכם, בלי הסכמה', 'זו כליאת שווא', 'אין עוולה, כי ההסכמה לניתוח כוללת כל הליך', 'זו בהכרח רק רשלנות בגילוי מידע'], 'c': 0, 'e': 'נכון. אין הסכמה לעצם הפעולה בכתף, ולכן מתאים ניתוח במסגרת התקיפה (בכפוף לחירום — ס׳ 24(8)). בפרשת דעקה, לעומת זאת, נחתמה הסכמה אך בלי מידע מספיק, והמקרה נבחן ברשלנות.'}, {'q': 'מה ההגנה לפי ס׳ 24(8) לפקודה?', 'o': ['מעשה בתום לב לטובת התובע, כשלא היה אפשר לקבל את הסכמתו ולא היה ניתן לדחות את המעשה', 'הגנה להורה המעניש ילדו', 'הגנה על מקרקעין', 'הגנה לחיילים'], 'c': 0, 'e': 'נכון. זו הגנת ״החירום״ — למשל טיפול מציל חיים במחוסר הכרה.'}, {'q': 'אדם נכנס בלי רשות, בשקט ובלי כוח, לחצר של שכנו. השכן מיד דחף אותו החוצה בכוח. האם עומדת לשכן הגנת ס׳ 24(2)?', 'o': ['לא, כי ס׳ 24 חל רק על הגנה עצמית', 'כן, תופש מקרקעין רשאי תמיד להשתמש בכוח', 'לא, כי כשהכניסה לא הייתה בכוח, תנאי להגנה הוא שהתופש ביקש קודם לצאת ונתן הזדמנות סבירה לעשות זאת בשלום', 'כן, אם הדחיפה לא גרמה חבלה'], 'c': 2, 'e': 'נכון. זו לשון ס׳ 24(2): קודם לבקש, לתת הזדמנות, ורק אז להשתמש בכוח סביר.'}, {'q': 'אדם חולה נפש, שנמצא בהליך הפלילי בלתי אחראי למעשיו, תקף ילד. הילד תבע אותו בנזיקין. מה ההלכה?', 'o': ['האחריות עוברת אוטומטית לבית החולים', 'הנתבע חב; בנזיקין אין הגנת אי־שפיות, אלא רק הגנה של חוסר שליטה ממש במעשה', 'התביעה תידחה בשל אי־שפיות', 'הפיצוי יוגבל לנזק ממוני בלבד'], 'c': 1, 'e': 'נכון. זו הלכת כרמי נ׳ סבג: רק מצב של אוטומטיזם, שבו אין מעשה רצוני, פוטר.'}, {'q': 'מה נדרש כדי שתתקיים ״שלילה מוחלטת״ של החירות בכליאת שווא?', 'o': ['שהכליאה תימשך לפחות שעה', 'שכל דרכי היציאה הסבירות חסומות, גם אם לא פיזית — למשל בהופעה כבעל סמכות', 'שהנכלא ייפגע פיזית', 'שהנכלא יהיה בחדר נעול'], 'c': 1, 'e': 'נכון. השלילה צריכה להיות מלאה — אין דרך יציאה סבירה — אך האמצעי יכול להיות פיזי או סמכותי.'}, {'q': 'מפגינים חסמו את הכניסה הראשית לבניין, אבל דלת אחורית נותרה פתוחה ובטוחה לשימוש. אדם שרצה להיכנס דרך הכניסה הראשית טוען לכליאת שווא. מה הדין?', 'o': ['זו תקיפה', 'זו כליאת שווא, כי נחסמה דרכו', 'אין כליאת שווא, כי השלילה לא הייתה מוחלטת — הייתה דרך סבירה אחרת', 'זו כליאת שווא רק אם החסימה ארכה יותר מעשר דקות'], 'c': 2, 'e': 'נכון. כשקיימת דרך יציאה או תנועה סבירה, אין שלילה מוחלטת.'}, {'q': 'אדם במדים, שהציג עצמו כפקח, אמר לנהג: ״אתה לא זז מפה עד שאחזור״. הנהג נשאר במקום שעה. התברר שלא הייתה לאיש כל סמכות. מה הדין?', 'o': ['אין עוולה, כי הנהג יכול היה ללכת', 'יש רק תקיפה בדרך של איום', 'יש כליאת שווא — שלילה מוחלטת ושלא כדין באמצעות הופעה כבעל סמכות', 'אין כליאה, כי לא נעשה שימוש בכוח'], 'c': 2, 'e': 'נכון. הנהג נשמע לסמכות שהוצגה, והשלילה הייתה בלי הצדקה.'}, {'q': 'לפי ס׳ 75 לחוק המעצרים, מה מהבאים אינו תנאי לעיכוב חוקי בידי אדם פרטי?', 'o': ['חשש שהחשוד יימלט או שזהותו אינה ידועה', 'החשד הוא לעבירה מהסוג המנוי (אלימות, פשע, גניבה, נזק של ממש לרכוש) שבוצעה בפני המעכב או שאדם אחר מצביע על החשוד', 'קבלת אישור טלפוני מראש מקצין משטרה', 'מסירה לשוטר ללא דיחוי ובתוך שלוש שעות לכל היותר'], 'c': 2, 'e': 'נכון. החוק אינו דורש אישור מוקדם; ההגבלות הן התנאים האחרים, וכן כוח סביר בלי חבלה (ס׳ 75(ג)).'}, {'q': 'מאבטח עיכב חשוד בגניבה שביצע בפניו, אך שמר אותו בחדר חמש שעות ולא הזמין משטרה. מה הדין?', 'o': ['כליאת שווא — לפחות על התקופה שחרגה מתנאי ס׳ 75 (מסירה ללא דיחוי, עד שלוש שעות)', 'רק תקיפה', 'אין עוולה אם התברר בסוף שהחשוד גנב', 'אין עוולה, כי העיכוב היה מוצדק בתחילתו'], 'c': 0, 'e': 'נכון. ס׳ 75(ב) מחייב מסירה לשוטר ללא דיחוי ומגביל את העיכוב לשלוש שעות.'}, {'q': 'מורה השאיר תלמיד בכיתה עשר דקות מההפסקה כעונש על הפרעה. מה ההגנה הרלוונטית?', 'o': ['אין הגנה, ולכן זו כליאת שווא', 'ס׳ 27(3) — אדם לא שפוי', 'ס׳ 24(1) — הגנה עצמית', 'ס׳ 27(6) — שלילה ארעית בלבד של חירות בידי מורה, לזמן נחוץ באופן סביר כדי שייטיב דרכו'], 'c': 3, 'e': 'נכון. ס׳ 27(6) מתיר הגבלה ארעית וחינוכית בידי הורה, אפוטרופוס או מורה.'}, {'q': 'שוטר עצר אדם על סמך חשד שהיה סביר לפי המידע שבידיו באותה עת; בהמשך התברר שהעצור חף מפשע. מה ההערכה הנכונה?', 'o': ['המדינה פטורה מכל אחריות במעצרים', 'זו כליאת שווא אוטומטית, כי העצור חף מפשע', 'ככלל המעצר היה כדין, כי סבירות החשד נבחנת לפי המידע בזמן המעצר', 'השוטר אחראי אישית תמיד'], 'c': 2, 'e': 'נכון. בחינת החוקיות היא לפי נקודת הזמן של המעצר (ובנוסף חלה הגנת ס׳ 6).'}, {'q': 'מה קבע ביהמ״ש בפרשת שוורץ?', 'o': ['שסוהר אחראי רק בפלילים', 'שהמדינה חסינה מתביעות על מעשי שוטרים', 'שתביעה על תקיפה בבית סוהר מתיישנת תוך שנה', 'שהמדינה, כמו כל תאגיד, אחראית שילוחית לעוולות עובדיה במהלך תפקידם, ויכולה לשאת באחריות גם על מעשים שהרשתה או אישררה'], 'c': 3, 'e': 'נכון. זו ההלכה שנקבעה בע״א 358/63, שעסק במכות שספג אדם מידי שוטרים וסוהרים.'}, {'q': 'מה ממחישה פרשת כרמלי לגבי היחס בין עוולות (״גישת הרשתות״)?', 'o': ['שכליאת שווא גוברת תמיד על הפרת חובה חקוקה', 'שאשפוז כפוי הוא תמיד כליאת שווא', 'שמותר לתבוע רק עוולה אחת על אותן עובדות', 'שאפשר לטעון כמה עוולות במקביל על אותה מסכת עובדתית, אבל הפיצוי נקבע לפי הנזק ואינו מוכפל'], 'c': 3, 'e': 'נכון. העוולות מצטברות כעילות, והפיצוי הוא פונקציה של הנזק; בפרשה התביעה נדחתה כי לא נגרם נזק.'}, {'q': 'נוסע הותקף בתחנה מרכזית בידי אדם זר, ותבע את מפעילת התחנה על כך שלא הציבה אבטחה. לפי פרשת וולאס נ׳ אגד, מה הדין?', 'o': ['המפעילה אחראית באופן מוחלט לכל תקיפה בשטחה', 'אין לדחות את התביעה על הסף; שאלת החובה למנוע מעשה פלילי של צד שלישי והקשר הסיבתי טעונות בירור עובדתי', 'התביעה נדחית על הסף, כי האחריות על התוקף בלבד', 'המפעילה אחראית בתקיפה, כי היא ״תקפה בעקיפין״'], 'c': 1, 'e': 'נכון. ביהמ״ש העליון החזיר את התיק לבירור לגופו; תקיפה ספונטנית אינה מוציאה אוטומטית את המקרה מגדר האחריות.'}, {'q': 'מה ההבדל בין הגנה עצמית בנזיקין (ס׳ 24(1)) לבין הגנה עצמית בפלילים?', 'o': ['בנזיקין נדרשים סבירות ויחס סביר בין הנזקים, וההוכחה היא לפי מאזן הסתברויות; לכן נאשם שזוכה בפלילים עלול לחוב בנזיקין', 'בנזיקין אין הגנה עצמית כלל', 'בפלילים אין דרישת מידתיות', 'אין כל הבדל'], 'c': 0, 'e': 'נכון. ס׳ 24(1) דורש סבירות ויחס סביר, ובנוסף מידת ההוכחה האזרחית נמוכה מזו הפלילית.'}, {'q': 'תקיפה מעוגנת ב:', 'o': ["ס' 23", "ס' 35", "ס' 63", "ס' 1"], 'c': 0, 'e': 'עוולה פרטיקולרית.'}, {'q': 'תקיפה כוללת:', 'o': ['רק מגע', 'גם ניסיון או איום אמין', 'רק נזק', 'רק כוונה לנזק'], 'c': 1, 'e': 'איום שמניח כוונה ויכולת.'}, {'q': '"כוח" בתקיפה כולל:', 'o': ['רק מכה', 'חום/אור/חשמל/ריח מזיקים', 'רק דחיפה', 'רק נשק'], 'c': 1, 'e': 'הגדרה רחבה.'}, {'q': 'כליאת שווא דורשת:', 'o': ['מחיצות פיזיות', 'שלילת חירות מוחלטת שלא כדין', 'נזק כספי', 'זמן ממושך'], 'c': 1, 'e': 'די במניעת יציאה, גם קצרה.'}, {'q': 'מה מאפיין עוולות פרטיקולריות?', 'o': ['ניסוח עקרוני', 'יסודות מוגדרים', 'דורשות רשלנות', 'חופפות לחוזים'], 'c': 1, 'e': 'בשונה מעוולות מסגרת.'}]
